ObjectId FindSet(string name) { foreach (ObjectId id in CivilDoc.Styles.LabelSetStyles.ProfileLabelSetStyles) { var s = (ProfileLabelSetStyle)Transaction.GetObject(id, OpenMode.ForRead); if (s.Name == name) return id; } return ObjectId.Null; }
ObjectId FindStyle(string name) { foreach (ObjectId id in CivilDoc.Styles.ProfileStyles) { var s = (ProfileStyle)Transaction.GetObject(id, OpenMode.ForRead); if (s.Name == name) return id; } return ObjectId.Null; }
var setGrade = FindSet("ARJV_ Profile Label Set"); var setNone = FindSet("_No Labels"); var stInv = FindStyle("ARJV_Design Profile"); var stCrown = FindStyle("Layout");
if (setGrade.IsNull || setNone.IsNull || stInv.IsNull || stCrown.IsNull) return new { error = "style or label set not found", setGrade = setGrade.IsNull, setNone = setNone.IsNull, stInv = stInv.IsNull, stCrown = stCrown.IsNull };
var lt = (LayerTable)Transaction.GetObject(Database.LayerTableId, OpenMode.ForWrite);
ObjectId Layer(string name, short color) { if (lt.Has(name)) return lt[name]; var rec = new LayerTableRecord { Name = name, Color = Autodesk.AutoCAD.Colors.Color.FromColorIndex(Autodesk.AutoCAD.Colors.ColorMethod.ByAci, color) }; var id = lt.Add(rec); Transaction.AddNewlyCreatedDBObject(rec, true); return id; }
var layInv = Layer("W9-PROF-INVERT", 1); var layCrown = Layer("W9-PROF-CROWN", 4);
var als = new Dictionary<string, Alignment>(); foreach (ObjectId aid in CivilDoc.GetAlignmentIds()) { var a = (Alignment)Transaction.GetObject(aid, OpenMode.ForRead); als[a.Name] = a; }
int made = 0, erased = 0, pvis = 0; var problems = new List<string>(); var ci = System.Globalization.CultureInfo.InvariantCulture;
foreach (var item in spec.Split(';'))
{
    if (string.IsNullOrWhiteSpace(item)) continue;
    var parts = item.Split('|'); var name = parts[0]; if (!als.ContainsKey(name)) { problems.Add("no alignment " + name); continue; }
    var al = als[name];
    try
    {
        var erasedHere = new List<ObjectId>();
        foreach (ObjectId pid in al.GetProfileIds()) { var p = (Profile)Transaction.GetObject(pid, OpenMode.ForRead); if (p.Name.StartsWith("GDP")) { p.UpgradeOpen(); p.Erase(); erased++; erasedHere.Add(pid); } }
        var nodes = parts[1].Split(',').Select(t => t.Split(':').Select(v => double.Parse(v, ci)).ToArray()).ToList();
        double s0 = al.StartingStation, s1 = al.EndingStation; double last = double.NegativeInfinity;
        var clean = new List<double[]>();
        foreach (var n in nodes) { double s = Math.Min(Math.Max(n[0], s0), s1 - 0.001); if (s <= last + 0.005) s = last + 0.01; if (s > s1 - 0.001) continue; clean.Add(new[] { s, n[1], n[2] }); last = s; }
        var invId = Profile.CreateByLayout("Invert " + name, al.ObjectId, layInv, stInv, setGrade); var inv = (Profile)Transaction.GetObject(invId, OpenMode.ForWrite);
        foreach (var n in clean) { inv.PVIs.AddPVI(n[0], n[1]); pvis++; }
        var crId = Profile.CreateByLayout("Crown " + name, al.ObjectId, layCrown, stCrown, setNone); var cr = (Profile)Transaction.GetObject(crId, OpenMode.ForWrite);
        foreach (var n in clean) cr.PVIs.AddPVI(n[0], n[2]);
        foreach (ObjectId vid in al.GetProfileViewIds())
        {
            var pv = (ProfileView)Transaction.GetObject(vid, OpenMode.ForWrite);
            var bot = pv.Bands.GetBottomBandItems(); bool changed = false;
            foreach (var b in bot) { if (b.Profile2Id.IsNull || erasedHere.Contains(b.Profile2Id)) { b.Profile2Id = invId; changed = true; } if (erasedHere.Contains(b.Profile1Id)) { b.Profile1Id = invId; changed = true; } }
            if (changed) pv.Bands.SetBottomBandItems(bot);
            var top = pv.Bands.GetTopBandItems(); changed = false;
            foreach (var b in top) { if (erasedHere.Contains(b.Profile2Id)) { b.Profile2Id = invId; changed = true; } if (erasedHere.Contains(b.Profile1Id)) { b.Profile1Id = invId; changed = true; } }
            if (changed) pv.Bands.SetTopBandItems(top);
        }
        made++;
    }
    catch (System.Exception ex) { problems.Add(name + ": " + ex.Message); }
}
return new { made, erased, pvis, problems };
